import { nucleusActions } from "@21n/products/nucleus/nucleus.actions";
import NucleusBaseLayer from "@21n/products/nucleus/base/NucleusBaseLayer.svelte";

export default {
  actions: nucleusActions,
  base: NucleusBaseLayer
};
import { memotronActions } from "@21n/products/memotron/memotron.actions";
import MemotronBaseLayer from "@21n/products/memotron/base/MemotronBaseLayer.svelte";

export default {
  actions: memotronActions,
  base: MemotronBaseLayer
};
import { pointronActions } from "@21n/products/pointron/pointron.actions";
import PointronBaseLayer from "@21n/products/pointron/base/PointronBaseLayer.svelte";

export default {
  actions: pointronActions,
  base: PointronBaseLayer
};
import { Extension, OverviewPanel, Product } from "@21n/products/product.type";
import { getProductNavConfig } from "./product-nav.config";
import { Resource } from "@21n/components/flux/resourceStores/resource.enum";
import { Action } from "@21n/types/action.enum";
import { MemotronAction } from "@21n/products/memotron/memotronAction.enum";
import { resourceConfig } from "@21n/components/flux/resourceStores/resource.config";
import type { IResourceTableConfig } from "@21n/components/flux/flux.type";
import type { ISelectItem } from "@21n/types/select.type";
import {
  nextProducts,
  nextResourceTableMap,
  nextNucleusOverviewPanelSwitcherItems
} from "@21n/next/product.config";
import { productRegistry } from "@21n/shared-config/product.config";
import type { IProductConfigBase as ISharedProductConfigBase } from "@21n/shared-config/product.config";

const isDev = import.meta.env?.DEV || false;

interface SettingsSection {
  children: (Action | MemotronAction | string)[];
  isHideTitle?: boolean;
  orientation?: "horizontal" | "vertical";
  section: string;
}

type IProductConfigBase = Omit<ISharedProductConfigBase, "resources"> & {
  resources: {
    browse: Resource[];
    table: Resource[];
  };
};

export interface IAppConfigBase extends IProductConfigBase {
  /**
