      if let downloadString = value["download"] as? String {
        let jsonData = Data(downloadString.utf8)
        let decoder = JSONDecoder()
        do {
          let req = try decoder.decode(DownloadRequest.self, from: jsonData)
          Log.info("Download request: \(req)")
          if let path = req.url {
