        location: window.location.toString(),
        protocol: window.location.protocol
      });
    }
    if (!engines) return -1;
    this.instance = new Surreal({
      engines: engines({
        strict: false,
        capabilities: {
          guest_access: true,
          functions: true,
          network_targets: true
        }
      })
