  store: IDBObjectStore
): Promise<IndexedDbRawRecord[]> {
  return new Promise((resolve, reject) => {
    const records: IndexedDbRawRecord[] = [];
    const request = store.openCursor();
    request.onerror = () => {
      reject(request.error ?? new Error(`Failed to read ${store.name}`));
    };
