    const mutationTokens = addOptimisticKvEntries(
      pendingUserPreferenceValues,
      n
    );
    userPreferencesLocal.update((current) =>
      normalizeUserPreferences({ ...current, ...n })
    );
    const mutation = datafn.kv.merge(Resource.globalPreferences, n);
