  const hasStoredUserInfo = Boolean(storedUserInfo);
  const hasStoredCloudIdentity = Boolean(
    authFnToken || storedUserInfo || storedUser
  );
  return {
    shouldUseBearerSession,
    authFnToken,
    offlineSessionId: offlineSessionId ?? undefined,
    hasStoredUserInfo,
