+async function readSurrealStoreBackups(
+  databaseName: string,
+  identity: LegacyLocalDataIdentity
+): Promise<LegacyLocalStoreBackup[]> {
+  const databaseIdentity = identity.userId ?? identity.dapId;
+  if (!databaseIdentity) {
