+            };
+          })
+        );
+        return {
+          name,
+          keyPath: "id",
+          autoIncrement: false,
+          indexes: [],
+          records
+        };
+      })
+    );
+    return stores.filter(
+      (store) => store.records.length > 0 || Boolean(store.error)
+    );
+  } finally {
+    await surreal.close();
+  }
