    try {
      let _file;
      if (typeof file === "object" && ("url" in file || "data" in file))
        _file = file;
      else if (typeof file === "string" && file.includes("http")) _file = file;
      else {
        _file = await this.select(file as IRecordId);
        if (!_file) return;
      }
      const contextStore = get(context);
      if (contextStore.isEmbed) {
