        }
        return;
      }
      let blob;
      try {
        if (_file.data) {
          blob = new Blob([_file.data], { type: _file.type });
        } else {
          const response = await fetch(_file.url);
          blob = await response.blob();
        }
      } catch (error: any) {
        toasts.error(defaultErrMessage);
        return;
      }
      if (!blob) {
        toasts.error(defaultErrMessage);
        return;
