  "http://127.0.0.1:5002"
];

function getParentOrigin(): string | null {
  try {
    return window.parent.location.origin;
  } catch (error) {
    return null;
  }
}

function isParentOriginTrusted(origin: string): boolean {
  if (TRUSTED_PARENT_ORIGINS.includes(origin)) {
