  gotoPostAuthRoute(params?: { isNewUser?: boolean }) {
    const targetPath = params?.isNewUser ? "/onboarding" : "/";
    logger.info({
      at: "account.gotoPostAuthRoute",
      targetPath,
      isNewUser: params?.isNewUser,
      currentPath:
        typeof window !== "undefined" ? window.location.pathname : undefined
    });
    if (params?.isNewUser) {
      appStore.gotoPath("/onboarding");
    } else {
      appStore.gotoPath("/");
    }
  }

  async signOut(params?: {
    isPreventDapIdClear?: boolean;
    isPreventRedirect?: boolean;
  }) {
    try {
      await destroyNucleumDatafn();
    } catch (error) {
      logger.error({ at: "account.signOut.destroyDatafn", error });
    }
    await clearCachedDatafnE2eeState();
    this.update(() => {
      const n = {
        sessionType: UserSessionType.UNDETERMINED,
        dataMode: UserDataMode.NONE
      };
      return n;
    });
    // TODO - this is causing issue in macOS app - signout is not working
    // await flux?.terminate();
    await signout(params, "signOut account.store");
  }
  async embedOAuthSignin(token: string) {
    await clientStorage.set(ClientStorageKey.AUTHFN_TOKEN, token);
    await clientStorage.remove(ClientStorageKey.STOKEN);
    const response = await this.resolveAuthFnSessionUserInfo();
    if (response?.userInfo) {
      this.signIn({
        userInfo: response?.userInfo,
        token
      });
    } else {
      logger.error({ at: "account.embedOAuthSignin", response });
    }
  }

  async signInFromAuthFnSession(params?: {
    token?: string;
    session?: any;
    regionId?: string;
    isNewUser?: boolean;
    isPreventRedirect?: boolean;
      return null;
    }
    return parse(userInfo)?.id ?? null;
  } else {
    const userInfo =
      typeof window !== "undefined"
        ? localStorage.getItem("userInfo")
        : undefined;
    if (userInfo) return parse(userInfo)?.id ?? null;
  }
  return null;
}

export async function signout(
  params?: { isPreventDapIdClear?: boolean; isPreventRedirect?: boolean },
  ctx?: string
) {
  logger.log({ at: "signout", context: ctx, params });
  try {
    const { authClient } = await import("@21n/components/account/auth");
    await (await authClient()).signOut({
      allSessions: false
    });
  } catch (error) {
    logger.error({ at: "authfn signout failed", error });
  }
  postDataToParent(EmbedDataMessage.ACCOUNT, {
    isLoggedIn: false
  });
  await clearLocalStorage(params);
  if (!params?.isPreventRedirect) goto("/account/login");
  async function clearLocalStorage(params?: { isPreventDapIdClear?: boolean }) {
    const env = await clientStorage.get(ClientStorageKey.ENV);
    const appData = await clientStorage.get(ClientStorageKey.APP_DATA);
    const product = await clientStorage.get(ClientStorageKey.PRODUCT);
    const dapId = params?.isPreventDapIdClear
      ? await clientStorage.get(ClientStorageKey.DAP_ID)
      : undefined;
    await clientStorage.clearAll();
    if (env) await clientStorage.set(ClientStorageKey.ENV, env);
    if (product) await clientStorage.set(ClientStorageKey.PRODUCT, product);
    if (appData) await clientStorage.set(ClientStorageKey.APP_DATA, appData);
    if (dapId) await clientStorage.set(ClientStorageKey.DAP_ID, dapId);
  }
}

export function isTokenExpired(token: string) {
  return !token;
}

