      try container.encode(dictionary.mapValues { AnyCodable($0) })
    default:
      throw EncodingError.invalidValue(
        self.value,
        EncodingError.Context(
          codingPath: container.codingPath, debugDescription: "AnyCodable cannot encode value"))
    }
  }
