+function countStoreRecords(store: IDBObjectStore): Promise<number> {
+  return new Promise((resolve, reject) => {
+    const request = store.count();
+    request.onerror = () => {
+      reject(request.error ?? new Error(`Failed to count ${store.name}`));
+    };
+    request.onsuccess = () => {
+      resolve(request.result);
+    };
+  });
+}
