+    request.onsuccess = () => {
+      const cursor = request.result;
+      if (!cursor) {
+        resolve(records);
+        return;
+      }
+      records.push({
+        key: cursor.primaryKey,
+        value: cursor.value
+      });
+      cursor.continue();
+    };
+  });
