+    return {
+      [serializationTypeKey]: "Blob",
+      type: value.type,
+      size: value.size,
+      dataBase64: arrayBufferToBase64(await value.arrayBuffer())
+    };
+  }
+  if (value instanceof ArrayBuffer) {
+    return {
+      [serializationTypeKey]: "ArrayBuffer",
+      dataBase64: arrayBufferToBase64(value)
+    };
+  }
