+  return (
+    summary?.databases.reduce(
+      (databaseTotal, database) =>
+        databaseTotal +
+        database.stores.reduce(
+          (storeTotal, store) =>
+            storeTotal +
+            ("count" in store ? store.count : store.records.length),
+          0
+        ),
+      0
+    ) ?? 0
+  );
+}
