+        databaseTotal +
+        database.stores.reduce((storeTotal, store) => {
+          if (!isImportableLegacyStore(store.name) || store.error) {
+            return storeTotal;
+          }
+          return (
+            storeTotal + ("count" in store ? store.count : store.records.length)
