+  for (const decision of pending) {
+    decision.isCloudUploadPending = false;
+  }
+  if (pending.length > 0) {
+    await clientStorage.set(
+      ClientStorageKey.LEGACY_LOCAL_DATA_RECOVERY,
+      decisions
+    );
+  }
